'use strict';
/* 鱼书 AI 语音大模型 · 多平台模板版
 * 平台预设: OpenAI / 硅基流动(SiliconFlow) / 自定义。登录平台拿 Key，填一次即可。
 */
const CFG_KEY='aitts.config';
const PLATFORMS={
  openai:{name:'OpenAI', url:'https://api.openai.com/v1/audio/speech', model:'tts-1', voices:['alloy','echo','fable','onyx','nova','shimmer']},
  silicon:{name:'硅基流动(SiliconFlow)', url:'https://api.siliconflow.cn/v1/audio/speech', model:'FunAudioLLM/SenseVoiceSmall', voices:['FunAudioLLM/SenseVoiceSmall']},
  aliyun:{name:'阿里百炼(DashScope)', url:'https://dashscope.aliyuncs.com/compatible-mode/v1/audio/speech', model:'qwen-audio-3.0-tts-flash', voices:['qwen-audio-3.0-tts-flash','cosyvoice-v3-flash']},
  custom:{name:'自定义', url:'', model:'tts-1', voices:['alloy']}
};
function text(v){ return v===undefined||v===null?'':String(v); }
function getCfg(){ try{ const c=reader.storage.get(CFG_KEY); return (c&&typeof c==='object')?c:{platform:'openai'}; }catch(_){ return {platform:'openai'}; } }
function plat(c){ var p=c.platform||'openai'; return PLATFORMS[p]||PLATFORMS.openai; }
module.exports.ttsVoices=async function(){ var c=getCfg(); var p=plat(c); var vs=(Array.isArray(c.voices)&&c.voices.length?c.voices:p.voices);
  return vs.map(function(v,i){ return { voiceKey:String(v), name:('AI · '+String(v)), locale:'zh-CN', gender:(i%2===0?'female':'male'), description:p.name+' 在线语音' }; }); };
module.exports.ttsSynthesize=async function(input){ var c=getCfg(); var p=plat(c); var url=text(c.url||p.url), key=text(c.apiKey), model=text(c.model||p.model);
  if(!/^https?:\/\//i.test(url)) throw new Error('请先在插件页选平台并填服务地址');
  if(!key) throw new Error('请先在插件页填入该平台的 API Key（登录平台控制台获取）');
  var t=text(input&&input.text); if(!t.trim()) throw new Error('朗读文本为空');
  var v=text(input&&input.voiceKey)||'alloy'; var sp=Math.max(0.25,Math.min(2,Number(input&&input.speed)||1));
  return { url:url, method:'POST',
    headers:{ 'Content-Type':'application/json', 'Authorization':'Bearer '+key },
    body:JSON.stringify({ model:model, input:t, voice:v, response_format:'mp3', speed:sp }),
    contentType:'audio/mpeg',
    cacheKey:'aitts:'+model+':'+v+':'+String(sp)+':'+(t.length>64?t.slice(0,64):t) };
};
module.exports.ui=async function(){ return { schemaVersion:1 }; };
module.exports.manage=async function(input){ var a=input&&input.action;
  if(a==='getConfig') return getCfg();
  if(a==='platforms') return Object.keys(PLATFORMS).map(function(k){ return {key:k,name:PLATFORMS[k].name,url:PLATFORMS[k].url,model:PLATFORMS[k].model}; });
  if(a==='saveConfig'){ var c=input.config||{}; reader.storage.set(CFG_KEY,{platform:c.platform||'openai',url:text(c.url),apiKey:text(c.apiKey),model:text(c.model),voices:Array.isArray(c.voices)&&c.voices.length?c.voices:[]}); return { ok:true }; }
  return { schemaVersion:1 };
};
